return items.map(item => {
  const msg = item.json;

  // 1. Target the nested address property directly from the Gmail schema
  let fromEmail = '';
  if (msg.from && msg.from.value && msg.from.value[0] && msg.from.value[0].address) {
    fromEmail = msg.from.value[0].address;
  } else if (msg.headers && msg.headers.from) {
    // Fallback parser if pulling headers raw
    const headerString = String(msg.headers.from);
    const emailMatch = headerString.match(/<([^>]+)>/);
    fromEmail = emailMatch ? emailMatch[1] : headerString;
  }

  // 2. Clean formatting variables safely
  fromEmail = String(fromEmail).toLowerCase().trim();

  return {
    json: {
      fromEmail,
      subject: msg.subject || '',
      inboundMessage: msg.text || msg.snippet || '',
      gmailMessageId: msg.id || ''
    }
  };
});

const inbound = $('Normalize Inbound Payload').first().json;
return items.map(item => ({
  json: {
    ...item.json,
    fromEmail: inbound.fromEmail,
    subject: inbound.subject,
    inboundMessage: inbound.inboundMessage,
    gmailMessageId: inbound.gmailMessageId
  }
}));

// Same fix as Workflow B: after the HTTP Request node, $json is Claude's raw
// API response, not the lead+message data. Pull the original back in by
// position from the node right before the HTTP call.
const originalItems = $('Merge Lead + Message').all().map(i => i.json);

return items.map((item, idx) => {
  const original = originalItems[idx] || {};
  const raw = item.json?.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = { intent: 'question', reply_text: '' };
  }

  return {
    json: {
      ...original,
      intent: parsed.intent,
      reply_text: parsed.reply_text || ''
    }
  };
});

